package sqltype

import (
	"context"
	"strings"
	"testing"
)

func TestMathScalarExpRangeNeighbors(t *testing.T) {
	// Independent 4000-digit decimal exponential rounded to an integer.
	const positive = ""
	for _, tc := range []struct{ input, want string }{{"5999", positive}, {"-5999", "0." + strings.Repeat("0", 1000)}, {"-5999.9999999999999999999999", "0." + strings.Repeat("0", 1000)}} {
		p, v := scalarProvider(t, "exp", Numeric, tc.input)
		got, err := p.Evaluate(context.Background(), v[0], v[1])
		if err != nil {
			t.Fatal(tc.input, err)
		}
		text, err := p.ResultUsage().Type.Output(context.Background(), got)
		if err != nil || text != tc.want {
			t.Fatalf("exp(%s) got %q want %q: %v", tc.input, text, tc.want, err)
		}
	}
}
